-- Additive P1/P3 hardening: audience-safe wallets/referrals and tenant-resolved evidence.

alter table public.referral_links add constraint referral_links_id_audience_unique unique(id,audience_type);
alter table public.referral_conversions add column audience_type text;
update public.referral_conversions c set audience_type=l.audience_type from public.referral_links l where l.id=c.referral_link_id;
alter table public.referral_conversions alter column audience_type set not null;
alter table public.referral_conversions add constraint referral_conversion_audience_check check(audience_type in('CLIENT','PROVIDER'));
alter table public.referral_conversions add constraint referral_conversion_link_audience_fk foreign key(referral_link_id,audience_type)references public.referral_links(id,audience_type)on delete restrict;

create function private.guard_referral_conversion_audience()returns trigger language plpgsql security definer set search_path=pg_catalog,public as $$declare expected text;begin select l.audience_type into expected from public.referral_links l where l.id=new.referral_link_id;if expected is null then raise exception'REFERRAL_REQUEST_DENIED'using errcode='42501';end if;if new.audience_type is null then new.audience_type:=expected;elsif new.audience_type<>expected then raise exception'REFERRAL_AUDIENCE_MISMATCH'using errcode='23514';end if;return new;end$$;
create trigger referral_conversion_audience_guard before insert or update of referral_link_id,audience_type on public.referral_conversions for each row execute function private.guard_referral_conversion_audience();
revoke all on function private.guard_referral_conversion_audience()from public,anon,authenticated,service_role;

create function private.valid_reward_organization_source(p_organization_id uuid,p_source_type text,p_source_id text)returns boolean language plpgsql stable security definer set search_path=pg_catalog,public as $$declare x uuid;begin if p_source_id!~'^[0-9a-f-]{36}$'then return false;end if;x:=p_source_id::uuid;return case p_source_type when'DIAGNOSTIC_RECOMMENDATION'then exists(select 1 from public.diagnostic_recommendations q where q.id=x and q.organization_id=p_organization_id)when'DIAGNOSTIC_OPPORTUNITY'then exists(select 1 from public.diagnostic_opportunities q where q.id=x and q.organization_id=p_organization_id)when'CLIENT_PROJECT'then exists(select 1 from public.client_projects q where q.id=x and q.organization_id=p_organization_id)when'CONTRACT'then exists(select 1 from public.contracts q where q.id=x and q.client_organization_id=p_organization_id)else false end;exception when invalid_text_representation then return false;end$$;
revoke all on function private.valid_reward_organization_source(uuid,text,text)from public,anon,authenticated,service_role;

create function private.valid_tenant_baseline_evidence(p_organization_id uuid,p_refs jsonb)returns boolean language plpgsql stable security definer set search_path=pg_catalog,public as $$declare e jsonb;x uuid;begin
 if jsonb_typeof(p_refs)<>'array'or jsonb_array_length(p_refs)=0 or jsonb_array_length(p_refs)>50 then return false;end if;for e in select value from jsonb_array_elements(p_refs)loop if jsonb_typeof(e)<>'object'or(select array_agg(k order by k)from jsonb_object_keys(e)k)<>array['id','registry']::text[]or coalesce(e->>'id','')!~'^[0-9a-f-]{36}$'then return false;end if;x:=(e->>'id')::uuid;if e->>'registry'='CLIENT_COMPLIANCE_EVIDENCE'then if not exists(select 1 from public.client_compliance_evidence q where q.id=x and q.organization_id=p_organization_id and q.review_status='VERIFIED')then return false;end if;elsif e->>'registry'='PROVIDER_DOCUMENT_VERSION'then if not exists(select 1 from public.provider_document_versions q where q.id=x and q.provider_organization_id=p_organization_id and q.status='VERIFIED'and(q.expires_on is null or q.expires_on>current_date))then return false;end if;else return false;end if;end loop;return true;exception when invalid_text_representation then return false;end$$;
create function private.guard_tenant_baseline_evidence()returns trigger language plpgsql security definer set search_path=pg_catalog,private as $$begin if not private.valid_tenant_baseline_evidence(new.organization_id,new.evidence_refs)then raise exception'VERIFIED_TENANT_EVIDENCE_REQUIRED'using errcode='23514';end if;return new;end$$;
create trigger baseline_submission_tenant_evidence_guard before insert on public.measurement_baseline_submissions for each row execute function private.guard_tenant_baseline_evidence();
revoke all on function private.valid_tenant_baseline_evidence(uuid,jsonb),private.guard_tenant_baseline_evidence()from public,anon,authenticated,service_role;

create or replace function public.record_reward_source_event(p_organization_id uuid,p_event_type text,p_audience_type text,p_source_reference_type text,p_source_reference_id text,p_eligibility_snapshot jsonb,p_evidence_refs jsonb,p_evidence_hash text,p_occurred_at timestamptz,p_idempotency_key text,p_correlation_id uuid default extensions.gen_random_uuid())returns jsonb language plpgsql security definer set search_path=pg_catalog,public,private,extensions as $$declare a uuid:=auth.uid();c public.referral_conversions%rowtype;h text;cached jsonb;x uuid;r jsonb;begin
 if not private.rewards_sensitive_aal2(a)then raise exception'REWARD_SOURCE_EVENT_DENIED'using errcode='42501';end if;if p_event_type!~'^[A-Z][A-Z0-9_.]{2,79}$'or p_audience_type not in('CLIENT_ORGANIZATION','REFERRED_CLIENT','REFERRED_PROVIDER')or p_source_reference_type!~'^[A-Z][A-Z0-9_]{2,63}$'or length(btrim(coalesce(p_source_reference_id,'')))not between 3 and 200 or jsonb_typeof(p_eligibility_snapshot)<>'object'or jsonb_typeof(p_evidence_refs)<>'array'or jsonb_array_length(p_evidence_refs)=0 or p_evidence_hash!~'^[0-9a-f]{64}$'or p_occurred_at>clock_timestamp()then raise exception'INVALID_REWARD_SOURCE_EVENT'using errcode='22023';end if;
 if p_audience_type='CLIENT_ORGANIZATION'then if not private.valid_reward_organization_source(p_organization_id,p_source_reference_type,p_source_reference_id)then raise exception'AUTHORITATIVE_ORGANIZATION_SOURCE_REQUIRED'using errcode='23514';end if;else if p_source_reference_type<>'REFERRAL_CONVERSION'or p_source_reference_id!~'^[0-9a-f-]{36}$'then raise exception'REWARD_REFERRAL_SOURCE_REQUIRED'using errcode='23514';end if;select*into c from public.referral_conversions where id=p_source_reference_id::uuid and target_organization_id=p_organization_id and conversion_stage in('VERIFIED','ACTIVE')and audience_type=case when p_audience_type='REFERRED_PROVIDER'then'PROVIDER'else'CLIENT'end;if not found or p_event_type<>'REFERRAL_VERIFIED'then raise exception'VERIFIED_REFERRAL_AUDIENCE_REQUIRED'using errcode='23514';end if;if(p_audience_type='REFERRED_PROVIDER'and not exists(select 1 from public.provider_profiles q where q.provider_organization_id=p_organization_id and q.company_status='VERIFIED'))or(p_audience_type='REFERRED_CLIENT'and not exists(select 1 from public.client_compliance_cases q where q.organization_id=p_organization_id and q.status='VERIFIED'))then raise exception'REWARD_AUDIENCE_SOURCE_MISMATCH'using errcode='23514';end if;end if;
 h:=private.canonical_request_hash(jsonb_build_object('org',p_organization_id,'event',p_event_type,'audience',p_audience_type,'source_type',p_source_reference_type,'source_id',p_source_reference_id,'eligibility',p_eligibility_snapshot,'evidence',p_evidence_refs,'evidence_hash',p_evidence_hash,'occurred_at',p_occurred_at));cached:=private.begin_rewards_command(p_organization_id,a,'reward.source_event.record',p_idempotency_key,h);if cached is not null then return cached;end if;insert into public.reward_source_events(organization_id,event_type,audience_type,source_reference_type,source_reference_id,eligibility_snapshot,evidence_refs,evidence_hash,occurred_at,recorded_by,correlation_id)values(p_organization_id,p_event_type,p_audience_type,p_source_reference_type,p_source_reference_id,p_eligibility_snapshot,p_evidence_refs,p_evidence_hash,p_occurred_at,a,p_correlation_id)returning id into x;r:=jsonb_build_object('outcome','REWARD_SOURCE_EVENT_RECORDED','source_event_id',x);insert into public.audit_events(organization_id,actor_user_id,actor_type,action,resource_type,resource_id,correlation_id,metadata,event_hash)values(p_organization_id,a,'USER','reward.source_event.recorded','reward_source_event',x::text,p_correlation_id,jsonb_build_object('event_type',p_event_type,'audience_type',p_audience_type,'source_reference_type',p_source_reference_type,'source_reference_id',p_source_reference_id),repeat('0',64));insert into public.event_outbox(organization_id,aggregate_type,aggregate_id,event_type,correlation_id,payload,idempotency_key)values(p_organization_id,'reward_source_event',x::text,'RewardSourceEventRecordedV1',p_correlation_id,r,p_idempotency_key);perform private.finish_rewards_command(p_organization_id,'reward.source_event.record',p_idempotency_key,r);return r;end$$;

create or replace function public.issue_credits(p_organization_id uuid,p_wallet_id uuid,p_source_type text,p_quantity bigint,p_expires_at timestamptz,p_library_id uuid,p_source_reference text,p_revenue_value_minor bigint,p_rule_version text,p_approval_reference text,p_idempotency_key text,p_correlation_id uuid default extensions.gen_random_uuid())returns jsonb language plpgsql security definer set search_path=pg_catalog,public,private,extensions as $$declare a uuid:=auth.uid();h text;r jsonb;e bigint;l uuid;wallet_kind text;reward_event uuid;begin
 if a is null or not private.credits_admin_access(a)then raise exception'CREDIT_ISSUE_DENIED'using errcode='42501';end if;if p_source_type not in('SUBSCRIPTION_GRANT','EXTRA_PURCHASE','BONUS','PROMOTION','ADMIN_GRANT')or p_quantity<=0 or p_expires_at<=clock_timestamp()or p_revenue_value_minor<0 or length(btrim(coalesce(p_source_reference,'')))<3 or length(btrim(coalesce(p_rule_version,'')))<1 or(p_source_type in('BONUS','PROMOTION','ADMIN_GRANT')and length(btrim(coalesce(p_approval_reference,'')))<3)then raise exception'INVALID_CREDIT_ISSUE'using errcode='22023';end if;select wallet_type into wallet_kind from public.credit_wallets where organization_id=p_organization_id and id=p_wallet_id and(wallet_type='CLIENT'or wallet_type='PROVIDER')for update;if wallet_kind is null then raise exception'CREDIT_WALLET_NOT_FOUND'using errcode='P0002';end if;
 if wallet_kind='PROVIDER'then if p_source_type<>'BONUS'or p_source_reference!~'^REWARD_EVENT:[0-9a-f-]{36}$'or p_approval_reference!~'^[0-9a-f-]{36}$'then raise exception'PROVIDER_REWARD_AUTHORITY_REQUIRED'using errcode='23514';end if;reward_event:=substring(p_source_reference from 14)::uuid;if not exists(select 1 from public.reward_award_approvals ap join public.reward_source_events se on se.id=ap.source_event_id and se.organization_id=ap.organization_id where ap.id=p_approval_reference::uuid and ap.organization_id=p_organization_id and ap.decision='APPROVED'and se.id=reward_event and se.audience_type='REFERRED_PROVIDER')then raise exception'PROVIDER_REWARD_AUTHORITY_REQUIRED'using errcode='23514';end if;elsif wallet_kind<>'CLIENT'then raise exception'UNSUPPORTED_CREDIT_WALLET_TYPE'using errcode='23514';end if;
 h:=private.canonical_request_hash(jsonb_build_object('organization',p_organization_id,'wallet',p_wallet_id,'source_type',p_source_type,'quantity',p_quantity,'expires_at',p_expires_at,'library',p_library_id,'source',p_source_reference,'revenue_minor',p_revenue_value_minor,'rule_version',p_rule_version,'approval',p_approval_reference));r:=private.begin_credit_command(p_organization_id,'credits.issue',p_idempotency_key,h,a);if r is not null then return r;end if;insert into public.credit_ledger_entries(organization_id,wallet_id,entry_type,quantity,idempotency_scope,idempotency_key,correlation_id,reference_type,reference_id,created_by)values(p_organization_id,p_wallet_id,'GRANT',p_quantity,'credits.issue',p_idempotency_key,p_correlation_id,p_source_type,p_source_reference,a)returning id into e;insert into public.credit_lots(organization_id,wallet_id,grant_entry_id,source_type,source_reference,quantity,expires_at,library_id,revenue_value_minor,rule_version,created_by)values(p_organization_id,p_wallet_id,e,p_source_type,p_source_reference,p_quantity,p_expires_at,p_library_id,p_revenue_value_minor,p_rule_version,a)returning id into l;r:=jsonb_build_object('outcome','CREDITS_ISSUED','wallet_id',p_wallet_id,'credit_lot_id',l,'entry_id',e,'quantity',p_quantity);insert into public.audit_events(organization_id,actor_user_id,actor_type,action,resource_type,resource_id,correlation_id,metadata,event_hash)values(p_organization_id,a,'USER','credits.issued','credit_lot',l::text,p_correlation_id,jsonb_build_object('source_type',p_source_type,'quantity',p_quantity,'approval_reference',p_approval_reference,'wallet_type',wallet_kind),repeat('0',64));insert into public.event_outbox(organization_id,aggregate_type,aggregate_id,event_type,correlation_id,payload,idempotency_key)values(p_organization_id,'credit_wallet',p_wallet_id::text,'CreditsGrantedV1',p_correlation_id,r,p_idempotency_key);perform private.finish_credit_command(p_organization_id,'credits.issue',p_idempotency_key,r);return r;end$$;

create or replace function public.award_reward(p_organization_id uuid,p_wallet_id uuid,p_rule_version_id uuid,p_trigger_reference_type text,p_trigger_reference_id text,p_anti_abuse_key_hash text,p_eligibility_evidence jsonb,p_approval_reference text,p_idempotency_key text,p_correlation_id uuid default extensions.gen_random_uuid())returns jsonb language plpgsql security definer set search_path=pg_catalog,public,private,extensions as $$declare a uuid:=auth.uid();v public.reward_rule_versions%rowtype;e public.reward_source_events%rowtype;ap public.reward_award_approvals%rowtype;recipient_total bigint;global_total bigint;last_at timestamptz;h text;cached jsonb;grant_id uuid;issued jsonb;r jsonb;child_key text;expected_wallet text;actual_wallet text;begin
 if not private.rewards_sensitive_aal2(a)then raise exception'REWARD_AWARD_AAL2_REQUIRED'using errcode='42501';end if;select*into v from public.reward_rule_versions where id=p_rule_version_id and status='ACTIVE'and effective_from<=clock_timestamp()and(effective_until is null or effective_until>clock_timestamp());if not found then raise exception'ACTIVE_REWARD_RULE_REQUIRED'using errcode='22023';end if;if jsonb_typeof(p_eligibility_evidence)<>'object'or(select array_agg(k order by k)from jsonb_object_keys(p_eligibility_evidence)k)<>array['source_event_id']::text[]or coalesce(p_eligibility_evidence->>'source_event_id','')!~'^[0-9a-f-]{36}$'or coalesce(p_approval_reference,'')!~'^[0-9a-f-]{36}$'or p_anti_abuse_key_hash!~'^[0-9a-f]{64}$'then raise exception'REWARD_AUTHORITY_EVIDENCE_REQUIRED'using errcode='22023';end if;select*into e from public.reward_source_events where id=(p_eligibility_evidence->>'source_event_id')::uuid and organization_id=p_organization_id;select*into ap from public.reward_award_approvals where id=p_approval_reference::uuid and organization_id=p_organization_id and source_event_id=e.id and rule_version_id=v.id and decision='APPROVED';if e.id is null or ap.id is null then raise exception'APPROVED_REWARD_SOURCE_REQUIRED'using errcode='23514';end if;if e.event_type<>v.trigger_event or e.audience_type<>v.audience_type or e.source_reference_type<>p_trigger_reference_type or e.source_reference_id<>p_trigger_reference_id or not(e.eligibility_snapshot@>v.eligibility_rule)or ap.decided_by=e.recorded_by then raise exception'REWARD_SOURCE_RULE_BINDING_FAILED'using errcode='23514';end if;
 expected_wallet:=case when v.audience_type='REFERRED_PROVIDER'then'PROVIDER'else'CLIENT'end;select wallet_type into actual_wallet from public.credit_wallets where id=p_wallet_id and organization_id=p_organization_id for update;if actual_wallet is null then raise exception'CREDIT_WALLET_NOT_FOUND'using errcode='P0002';end if;if actual_wallet<>expected_wallet then raise exception'REWARD_WALLET_AUDIENCE_MISMATCH'using errcode='23514';end if;h:=private.canonical_request_hash(jsonb_build_object('organization',p_organization_id,'wallet',p_wallet_id,'rule_version',v.id,'source_event',e.id,'approval',ap.id,'anti_abuse_hash',p_anti_abuse_key_hash));cached:=private.begin_rewards_command(p_organization_id,a,'reward.award',p_idempotency_key,h);if cached is not null then return cached;end if;perform pg_advisory_xact_lock(hashtextextended('reward-award:'||v.rule_code,0));select coalesce(sum(g.quantity),0),max(g.granted_at)into recipient_total,last_at from public.reward_grants g where g.organization_id=p_organization_id and g.rule_code=v.rule_code and g.granted_at>=clock_timestamp()-make_interval(days=>v.window_days);select coalesce(sum(g.quantity),0)into global_total from public.reward_grants g where g.rule_code=v.rule_code and g.granted_at>=clock_timestamp()-make_interval(days=>v.window_days);if recipient_total+v.bonus_credits>v.per_recipient_cap_credits then raise exception'REWARD_RECIPIENT_CAP_EXCEEDED'using errcode='23514';end if;if global_total+v.bonus_credits>v.global_cap_credits then raise exception'REWARD_GLOBAL_CAP_EXCEEDED'using errcode='23514';end if;if last_at is not null and last_at+make_interval(hours=>v.cooldown_hours)>clock_timestamp()then raise exception'REWARD_COOLDOWN_ACTIVE'using errcode='23514';end if;
 child_key:='reward-credit-'||encode(extensions.digest(convert_to(p_idempotency_key,'UTF8'),'sha256'),'hex');issued:=public.issue_credits(p_organization_id,p_wallet_id,'BONUS',v.bonus_credits,clock_timestamp()+make_interval(days=>v.credit_validity_days),null,'REWARD_EVENT:'||e.id::text,0,v.rule_code||'-V'||v.version_number::text,ap.id::text,child_key,p_correlation_id);insert into public.reward_grants(organization_id,wallet_id,rule_version_id,rule_code,trigger_reference_type,trigger_reference_id,anti_abuse_key_hash,eligibility_evidence,quantity,credit_ledger_entry_id,credit_lot_id,approval_reference,correlation_id,idempotency_key,granted_by)values(p_organization_id,p_wallet_id,v.id,v.rule_code,e.source_reference_type,e.source_reference_id,p_anti_abuse_key_hash,jsonb_build_object('source_event_id',e.id,'source_evidence_hash',e.evidence_hash,'approval_id',ap.id),v.bonus_credits,(issued->>'entry_id')::bigint,(issued->>'credit_lot_id')::uuid,ap.id::text,p_correlation_id,p_idempotency_key,a)returning id into grant_id;r:=jsonb_build_object('outcome','REWARD_GRANTED','reward_grant_id',grant_id,'source_event_id',e.id,'approval_id',ap.id,'quantity',v.bonus_credits,'credit_lot_id',issued->'credit_lot_id');insert into public.audit_events(organization_id,actor_user_id,actor_type,action,resource_type,resource_id,correlation_id,metadata,event_hash)values(p_organization_id,a,'USER','reward.granted','reward_grant',grant_id::text,p_correlation_id,jsonb_build_object('rule_version_id',v.id,'source_event_id',e.id,'approval_id',ap.id,'quantity',v.bonus_credits,'wallet_type',actual_wallet),repeat('0',64));insert into public.event_outbox(organization_id,aggregate_type,aggregate_id,event_type,correlation_id,payload,idempotency_key)values(p_organization_id,'reward_grant',grant_id::text,'RewardGrantedV1',p_correlation_id,r,p_idempotency_key);perform private.finish_rewards_command(p_organization_id,'reward.award',p_idempotency_key,r);return r;end$$;

create or replace function public.record_referral_touchpoint(p_referral_code text,p_touchpoint_type text,p_visitor_key_hash text,p_idempotency_key text,p_correlation_id uuid default extensions.gen_random_uuid())returns jsonb language plpgsql security definer set search_path=pg_catalog,public,private,extensions as $$declare a uuid:=auth.uid();l public.referral_links%rowtype;h text;cached jsonb;x bigint;r jsonb;begin if a is null then raise exception'REFERRAL_REQUEST_DENIED'using errcode='42501';end if;if p_touchpoint_type not in('LINK_OPENED','REGISTRATION_STARTED')or p_visitor_key_hash!~'^[0-9a-f]{64}$'then raise exception'REFERRAL_REQUEST_DENIED'using errcode='42501';end if;select*into l from public.referral_links where referral_code=upper(p_referral_code)and status='ACTIVE'and expires_at>clock_timestamp();if not found then raise exception'REFERRAL_REQUEST_DENIED'using errcode='42501';end if;h:=private.canonical_request_hash(jsonb_build_object('link',l.id,'type',p_touchpoint_type,'visitor_hash',p_visitor_key_hash));cached:=private.begin_rewards_command(l.source_organization_id,a,'referral.touchpoint',p_idempotency_key,h);if cached is not null then return cached;end if;insert into public.referral_touchpoints(referral_link_id,source_organization_id,touchpoint_type,visitor_key_hash,correlation_id,actor_user_id)values(l.id,l.source_organization_id,p_touchpoint_type,p_visitor_key_hash,p_correlation_id,a)returning id into x;r:=jsonb_build_object('outcome','REFERRAL_TOUCHPOINT_RECORDED','touchpoint_id',x,'touchpoint_type',p_touchpoint_type);insert into public.audit_events(organization_id,actor_user_id,actor_type,action,resource_type,resource_id,correlation_id,metadata,event_hash)values(l.source_organization_id,a,'USER','referral.touchpoint.recorded','referral_touchpoint',x::text,p_correlation_id,jsonb_build_object('referral_link_id',l.id,'touchpoint_type',p_touchpoint_type),repeat('0',64));insert into public.event_outbox(organization_id,aggregate_type,aggregate_id,event_type,correlation_id,payload,idempotency_key)values(l.source_organization_id,'referral_link',l.id::text,'ReferralTouchpointRecordedV1',p_correlation_id,r,p_idempotency_key);perform private.finish_rewards_command(l.source_organization_id,'referral.touchpoint',p_idempotency_key,r);return r;end$$;

revoke all on function public.issue_credits(uuid,uuid,text,bigint,timestamptz,uuid,text,bigint,text,text,text,uuid),public.award_reward(uuid,uuid,uuid,text,text,text,jsonb,text,text,uuid),public.record_reward_source_event(uuid,text,text,text,text,jsonb,jsonb,text,timestamptz,text,uuid),public.record_referral_touchpoint(text,text,text,text,uuid)from public,anon,authenticated,service_role;
grant execute on function public.issue_credits(uuid,uuid,text,bigint,timestamptz,uuid,text,bigint,text,text,text,uuid),public.award_reward(uuid,uuid,uuid,text,text,text,jsonb,text,text,uuid),public.record_reward_source_event(uuid,text,text,text,text,jsonb,jsonb,text,timestamptz,text,uuid),public.record_referral_touchpoint(text,text,text,text,uuid)to authenticated;
notify pgrst,'reload schema';
